import{_ as e,c as r,o as p,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"40、【解】 坎下震上","description":"周易尚氏學 - 40、【解】 坎下震上","frontmatter":{"title":"40、【解】 坎下震上","description":"周易尚氏學 - 40、【解】 坎下震上"},"headers":[],"relativePath":"classics/shangshi/045.md","filePath":"classics/shangshi/045.md"}'),s={name:"classics/shangshi/045.md"};function h(t,a,l,n,c,d){return p(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_40、【解】-坎下震上" tabindex="-1">40、【解】 坎下震上 <a class="header-anchor" href="#_40、【解】-坎下震上" aria-label="Permalink to “40、【解】 坎下震上”">​</a></h1><p>震出險故曰解。歸藏作荔。荔與離通。上林賦。答（上草）還離支。離支即荔支。千祿字書。離支。俗作荔支。是離荔音同通用。離即解也。義與周易同。坤位西南。四居坤初。前臨重陰、陽得陰則通。故利西南。五得敵。故不利往。來複於二。各當其位。故曰其來複吉。有攸往。謂二往五。夙早也。禮記孔子間居。夙夜基命有密。疏夙即聽也。聽明也。二坎為夜。五震為晨。二往五則由夜及晨而天明矣。明故吉也。舊解于吉之故。皆言早往得位故吉。而王注詁夙為速尤誤。豈知詩書皆以夙與夜對言。夙為早者。言早晨也。非速也。</p><p>彖曰。解。險以動。動而免乎險。解。解利西南。往得眾也。無所往。其來複吉。乃得中也。有攸往夙吉。往有功也。天地解而雷雨作。雷雨作而百果草木皆甲坼。解之時大矣哉。</p><p>坎險震動。震在外。動而出險。故曰解。六五前遇陰。故曰無所往。來居二。居中當位。故吉。九二往居五。故有功。雷震坎雨。是天地解也。震為春。為百果草木。離為甲。孫星衍雲。甲皮也。震動故甲拆。訴說文裂也。言草木當春。得雷雨胚胎迸裂。蓓蕾怒發。芽　潛滋。而外甲訴也。史記律書。甲者言萬物剖符甲而出。又禮月令。其日甲乙。鄭注云。時萬物。皆解孚甲。皆甲拆之的解也。乃馬陸皆讀訴為宅。雲根也。愚以為訴宅音同。故通用。若以宅為根。則古無此訓。且草木未得雷雨之先。豈皆無孚甲無根乎。鄭康成蓋讀與馬陸同。而知其難通。故又曰。皆讀如人倦之解，以濟其窮。若曰皆甲宅。即解甲宅也。豈知甲宅即甲訴。不必如是穿鑿。且甲可解。根如何解哉。是仍不通也。然由鄭說。可悟以宅為根之非矣。乃雅麗堂刻本從惠棟校。竟改集解甲拆為甲宅。豈知苟注本作甲坼。故曰草木萌芽。萌芽。即釋拆義也。若作宅。苟胡以不釋。且釋文早言之矣。明本集解可證也。陸道平作纂疏。不顧荀注義如何。亦改作宅。致傳文與注不相應。真可異已。釋文只雲馬陸作宅。後集荀注者。如孫堂如馬國翰。皆改苟注作宅。可謂盲從。</p><h3 id="象曰。雷雨作。解。君子以教過宥罪。" tabindex="-1">象曰。雷雨作。解。君子以教過宥罪。 <a class="header-anchor" href="#象曰。雷雨作。解。君子以教過宥罪。" aria-label="Permalink to “象曰。雷雨作。解。君子以教過宥罪。”">​</a></h3><p>坎為罪過。震為解。故赦過宥罪。</p><p>初六。無咎。</p><p>承陽有應。雖失位。得無咎也。</p><h3 id="象曰。剛柔之際。義無咎也。" tabindex="-1">象曰。剛柔之際。義無咎也。 <a class="header-anchor" href="#象曰。剛柔之際。義無咎也。" aria-label="Permalink to “象曰。剛柔之際。義無咎也。”">​</a></h3><p>際交也。言初承陽。剛柔交際。故義得無咎。</p><p>九二。田獲三狐。得黃矢。貞吉。</p><p>坎為狐。坎陷故為獲。二應在五。五震為田獵。數三。故曰田獲三狐。坎為矢。互離色黃。故曰得黃矢。貞吉者。卜問吉也。諸家皆以離為矢。離雖為甲兵。然若斧象則專屬兌。矢則專象坎。坎為棘為匕為直為穿。故為矢。經從未以離為矢。</p><h3 id="象曰。九二貞吉。得中道也。" tabindex="-1">象曰。九二貞吉。得中道也。 <a class="header-anchor" href="#象曰。九二貞吉。得中道也。" aria-label="Permalink to “象曰。九二貞吉。得中道也。”">​</a></h3><p>離為道。二中位。故曰中道。</p><p>六三。負且乘。致寇至。貞吝。</p><p>三不當位。坎為車。三在車上。故曰乘。上震向外視之艮。艮為負何。故曰負且乘。坎為寇。三上下皆坎。故曰致寇至。古者君子方得乘車。若負戴則為小人之事。今負且乘焉。望之不似。則盜賊從而生心。故曰致寇至。言招致使來也。致卜問吝矣。貞吝與上貞吉為對文。故夫從虞氏以貞吉為之正者非也。</p><h3 id="象曰。負且乘。亦可且也。自我致戎。又誰咎也。" tabindex="-1">象曰。負且乘。亦可且也。自我致戎。又誰咎也。 <a class="header-anchor" href="#象曰。負且乘。亦可且也。自我致戎。又誰咎也。" aria-label="Permalink to “象曰。負且乘。亦可且也。自我致戎。又誰咎也。”">​</a></h3><p>說文戎兵也。寇至故謂致戎。</p><p>九四。解而拇。朋至斯孚。</p><p>拇。陸績雲。足大指也。王肅雲。手大指。手指於震象不合。故陸注是也。震為足。四前遇重陰。陽遇陰則通。故曰解而拇。言利往也。復家雲。朋來無咎。陰以陽為朋。九四前遇重陰。下乘陰。陰孚於陽。故曰朋至斯孚。言上下陰其共於四也。彖傳謂往得眾。指此爻也。舊解皆從虞翻說。謂四陽從初。下兌故朋至斯軍。致孚義全晦。</p><h3 id="象曰。解而拇。未當位也。" tabindex="-1">象曰。解而拇。未當位也。 <a class="header-anchor" href="#象曰。解而拇。未當位也。" aria-label="Permalink to “象曰。解而拇。未當位也。”">​</a></h3><p>解而拇。前進也。四失位。進至五則當位矣。申解而拇之故也。</p><p>六五。君子維有解。吉。有孚於小人。</p><p>震為君子謂四。君子維有解。言四宜升五。當位而吉。小人謂陰。四升五成坎。坎上下皆陰。有孚維心亨。故曰有率於小人。</p><h3 id="象曰。君子有解。小人退也。" tabindex="-1">象曰。君子有解。小人退也。 <a class="header-anchor" href="#象曰。君子有解。小人退也。" aria-label="Permalink to “象曰。君子有解。小人退也。”">​</a></h3><p>君子有解。謂九四升五。小人退。謂五退居四。釋爻義可謂至明白矣。</p><p>上六。公用射隼於高墉之上。獲之無不利。</p><p>震為公為射為隼。伏龔為塘為高。、六居賣上。故射隼於高墉之上。蓋卦為重坎。上六履重坎之上。動作如意。故獲之無不利也。震射左氏象。震為鴻鵠故為隼。俱見易林。詳焦氏易詁。</p><h3 id="象曰。公用射隼。以解悖也。" tabindex="-1">象曰。公用射隼。以解悖也。 <a class="header-anchor" href="#象曰。公用射隼。以解悖也。" aria-label="Permalink to “象曰。公用射隼。以解悖也。”">​</a></h3><p>坎為悖。上六居重坎之外。故曰解悖。</p>',30)])])}const f=e(s,[["render",h]]);export{_ as __pageData,f as default};
